      (0,'nature','Which animal makes honey?','أي حشرة تصنع العسل؟',[('Bee','نحلة'),('Ant','نملة'),('Fly','ذبابة'),('Butterfly','فراشة')],'Bees make honey from nectar.','يصنع النحل العسل من الرحيق.'),
      (0,'everyday','How many wheels does an ordinary bicycle have?','كم عجلة للدراجة الهوائية العادية؟',[('2','2'),('3','3'),('4','4'),('6','6')],'An ordinary bicycle has two wheels.','للدراجة الهوائية العادية عجلتان.'),
      (0,'world','Which of these is a continent?','أيّ هذه قارة؟',[('Africa','أفريقيا'),('Morocco','المغرب'),('Rabat','الرباط'),('Atlantic','الأطلسي')],'Africa is a continent.','أفريقيا قارة.'),
      (0,'nature','Which part of a plant is usually green and captures sunlight?','أي جزء من النبات غالباً أخضر ويلتقط ضوء الشمس؟',[('Leaf','ورقة'),('Root','جذر'),('Seed','بذرة'),('Bark','لحاء')],'Leaves capture sunlight for photosynthesis.','تلتقط الأوراق ضوء الشمس للبناء الضوئي.'),
      (0,'science','Which material is attracted to an ordinary magnet?','أي مادة يجذبها المغناطيس العادي؟',[('Iron','الحديد'),('Wood','الخشب'),('Paper','الورق'),('Glass','الزجاج')],'Iron is attracted to magnets.','يجذب المغناطيس الحديد.'),
