      (1,'science','What gas do plants take in during photosynthesis?','ما الغاز الذي تمتصه النباتات أثناء البناء الضوئي؟',[('Carbon dioxide','ثاني أكسيد الكربون'),('Helium','الهيليوم'),('Hydrogen','الهيدروجين'),('Neon','النيون')],'Plants use carbon dioxide in photosynthesis.','تستخدم النباتات ثاني أكسيد الكربون في البناء الضوئي.'),
      (1,'world','Which imaginary line divides Earth into northern and southern hemispheres?','ما الخط الوهمي الذي يقسم الأرض إلى نصفين شمالي وجنوبي؟',[('Equator','خط الاستواء'),('Prime meridian','خط غرينتش'),('Horizon','الأفق'),('Coastline','الساحل')],'The equator divides the northern and southern hemispheres.','يفصل خط الاستواء بين نصفي الكرة الشمالي والجنوبي.'),
