    for level,category,en,ar,options,ex,exar in facts:
        for word,meaning in options:arabic_answers[word]=meaning
        add('general','choice',level,category,en,ar,'',options[0][0],[w for w,_ in options],ex,exar,hint=ex,hint_ar=exar)
    search_words=[w.upper() for words in vocab for w,_ in words if 3<=len(w)<=8]
    for level in range(3):
        selected=search_words[level::3]
        for word in selected:add('puzzles','search',level,'word-search','Find the hidden word','ابحث عن الكلمة المخفية',word,word,ex=f'You found {word}. Follow a single row or column.',exar=f'وجدت {word}. اتبع صفاً واحداً أو عموداً واحداً.',hint='The word is placed straight across or down.',hint_ar='توجد الكلمة أفقياً أو عمودياً في خط مستقيم.')
        for family in ['objects','nature','animals']:add('puzzles','memory',level,'memory','Match the pairs','اعثر على الأزواج المتطابقة','', 'matched',Image=family,ex=f'All {family} pairs matched. Notice positions before choosing.',exar='وجدت كل الأزواج. لاحظ المواقع قبل الاختيار.',hint='Remember one position at a time.',hint_ar='تذكّر موقعاً واحداً في كل مرة.')
        for start in range(1,9):
            step=(level+1)*((start%4)+2);seq=[start+step*n for n in range(5)];answer=seq[-1]
            add('puzzles','choice',level,'patterns','What comes next?','ما العدد التالي؟',' · '.join(map(str,seq[:-1]))+' · ?',str(answer),[str(answer),str(answer+1),str(answer-1),str(answer+step)],ex=f'Add {step} each time. The next number is {answer}.',exar=f'نضيف {step} كل مرة. العدد التالي {answer}.',hint=f'Compare the difference between neighbouring numbers.',hint_ar='قارن الفرق بين كل عددين متتاليين.')
            factor=2 if level==0 else 3 if level==1 else 4;seq=[start*factor**n for n in range(5)];answer=seq[-1]
            add('puzzles','choice',level,'patterns','Find the multiplying pattern','اكتشف نمط الضرب',' · '.join(map(str,seq[:-1]))+' · ?',str(answer),[str(answer),str(answer+factor),str(answer-factor),str(answer+1)],ex=f'Multiply by {factor} each step.',exar=f'نضرب في {factor} في كل خطوة.',hint='Try multiplying instead of adding.',hint_ar='جرّب الضرب بدلاً من الجمع.')
    odd=[('Apple',['Pear','Peach','Potato'],'Potato','The potato is not a fruit.','البطاطس ليست فاكهة.'),('Cat',['Dog','Rabbit','Spoon'],'Spoon','The spoon is not an animal.','الملعقة ليست حيواناً.'),('Circle',['Square','Triangle','Milk'],'Milk','Milk is not a shape.','الحليب ليس شكلاً.'),('Monday',['Tuesday','Friday','April'],'April','April is a month, not a day of the week.','أبريل شهر وليس يوماً من أيام الأسبوع.'),('Red',['Blue','Green','Chair'],'Chair','Chair is not a colour.','الكرسي ليس لوناً.'),('Guitar',['Piano','Violin','Window'],'Window','A window is not a musical instrument.','النافذة ليست آلة موسيقية.')]
    arabic_answers.update({'Pear':'كمثرى','Peach':'خوخ','Potato':'بطاطس','Spoon':'ملعقة','Circle':'دائرة','Square':'مربع','Triangle':'مثلث','Milk':'حليب','Monday':'الاثنين','Tuesday':'الثلاثاء','Friday':'الجمعة','April':'أبريل','Red':'أحمر','Blue':'أزرق','Green':'أخضر','Chair':'كرسي','Guitar':'غيتار','Piano':'بيانو','Violin':'كمان','Window':'نافذة','Apple':'تفاحة','Cat':'قطة','Dog':'كلب','Rabbit':'أرنب'})
    for level in range(3):
        for first,others,answer,ex,exar in odd:add('puzzles','choice',level,'logic','Which one does not belong?','أي كلمة لا تنتمي إلى المجموعة؟','',answer,[first]+others,ex,exar,hint='Think about what the other three have in common.',hint_ar='فكّر فيما يجمع الكلمات الثلاث الأخرى.')
